import java.util.*;
public class QuadraticProbingHashTable { String[] a=new String[11]; int hash(String s){return Math.abs(s.hashCode())%a.length;} void add(String s){int h=hash(s);for(int j=0;j<a.length;j++){int i=(h+j*j)%a.length;if(a[i]==null){a[i]=s;return;}}} public static void run(){QuadraticProbingHashTable h=new QuadraticProbingHashTable();for(String s:new String[]{"red","black","tree"})h.add(s);System.out.println("Quadratic probing table="+Arrays.toString(h.a));System.out.println("Quadratic probes reduce primary clustering; expected O(1) at safe load factors.\n");} public static void main(String[] args){run();}}
